require 'vendor/autoload.php';
use PhpOffice\PhpSpreadsheet\Spreadsheet;

// Case 1: remove column A when B has null
$s = new Spreadsheet(); $sh = $s->getActiveSheet();
$sh->fromArray([['a1','b1','c1'],['a2',null,'c2']]);
$sh->removeColumn('A');
var_export($sh->toArray(null, true, true, true)); echo "\n\n";

